import {
  IsNotEmpty,
  IsString,
} from 'class-validator';
/**
 * Request DTO for fetching the KYC documents
 * applicable to the logged-in user.
 * The user_token is the encrypted user identifier
 * generated by the existing authentication flow.
 * The backend does not decrypt or modify the token.
 * It is passed directly to the stored procedure.
 */
export class KycDocumentsDto {
  @IsString()
  @IsNotEmpty()
  user_token!: string;
}
/**
 * Request DTO for uploading or re-uploading
 * a user's KYC document using multipart/form-data.
 * The actual file is received separately through
 * the controller's @UploadedFile() parameter.
 * The backend generates the document URL/path
 * and passes it to the KYC stored procedure.
 */
export class KycUploadDto {
  @IsString()
  @IsNotEmpty()
  user_id!: string;
  @IsString()
  @IsNotEmpty()
  doc_id!: string;
}
